package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ScrubFieldsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property scrub fields of observed source ")
  void test_scrub_fields_v_o_builder() {
    Assertions.assertFalse(ScrubFieldsVO.nullValue().getScrubFields().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ScrubFieldsVO.tryFrom(null).getScrubFields().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ScrubFieldsVO.from("one").getScrubFields().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ScrubFieldsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ScrubFieldsVO.from("one").toString());
  }
}
